  const windowId = resolveCurrentWindowId(cp, task.ownerWindowId)
  if (!windowId) {
    return { tabId: null, needsTarget: true, reason: '작업할 창을 찾을 수 없습니다 — 창에서 다시 시작해 주세요.' }
