156	/** width x height 8비트 RGB(colorType=2) PNG 를 순수 zlib 으로 조립한다. colorFn(x,y) -> [r,g,b]. */
157	function encodePng(width, height, colorFn) {
158	  const rowBytes = width * 3
159	  const raw = Buffer.alloc((rowBytes + 1) * height)
160	  for (let y = 0; y < height; y++) {
161	    const rowStart = y * (rowBytes + 1)
162	    raw[rowStart] = 0 // 필터 없음
163	    for (let x = 0; x < width; x++) {
164	      const [r, g, b] = colorFn(x, y)
165	      const off = rowStart + 1 + x * 3
166	      raw[off] = r & 0xff
167	      raw[off + 1] = g & 0xff
168	      raw[off + 2] = b & 0xff
169	    }
170	  }
171	  const compressed = zlib.deflateSync(raw)
172	  const ihdr = Buffer.alloc(13)
173	  ihdr.writeUInt32BE(width, 0)
174	  ihdr.writeUInt32BE(height, 4)
175	  ihdr[8] = 8  // bit depth
176	  ihdr[9] = 2  // color type: truecolor RGB
177	  ihdr[10] = 0 // compression method
178	  ihdr[11] = 0 // filter method
179	  ihdr[12] = 0 // interlace method
180	  return Buffer.concat([
181	    PNG_SIGNATURE,
182	    pngChunk('IHDR', ihdr),
183	    pngChunk('IDAT', compressed),
184	    pngChunk('IEND', Buffer.alloc(0)),
185	  ])
186	}
