    '- 반드시 도구를 호출하세요(설명만 하지 말고). thought 인자에 이유를 한 문장으로.',
    '',
    '# 사용자가 지시한 작업',
    task,
  ].join('\n') + (getSetting('ai').memoryEnabled ? memoryBlock(1500) : '') + agentFilesBlock()
}

