// ===== 클릭 대상이 "어느 글" 인가 (댓글·좋아요 중복 방지용 신원) =====
//
// 왜 페이지 주소만으로는 안 되는가: 피드에서는 글 10개가 **한 주소**를 공유한다. 주소로만 키를 잡으면
// 첫 글에 댓글을 단 뒤 둘째 글의 댓글이 "이미 했다"로 막힌다(과차단). 반대로 아무 키나 쓰면 재시도가
// 같은 글에 두 번 단다(미차단).
//
// 그래서 클릭한 요소에서 **위로 올라가며** 그 글의 정체를 찾는다.
//  ① 조상 안의 퍼머링크(`<a href>`, 현재 주소와 다른 http(s)) — 가장 안정적이다.
//  ② 없으면 조상의 제목(h1~h4) — 댓글이 달려 본문 아래가 길어져도 제목은 그대로다.
//     (본문 앞부분을 지문으로 쓰면 댓글이 추가되는 순간 지문이 바뀌어 중복 방지가 샌다.)
//  ③ 둘 다 없으면 **모른다고 답한다**(ambiguous). 호출자가 사람에게 묻는다 — 추측해서 누르지 않는다.
export interface EngageTargetProbe {
  /** 그 글의 고유 주소(찾았을 때만). */
  permalink: string
  /** 제목 텍스트(퍼머링크가 없을 때의 차선 신원). */
  heading: string
  /** 목록형 화면인가(항목이 여러 개 반복) — 신원을 못 찾았을 때 "모른다"와 "단일 글"을 가른다. */
  listLike: boolean
  /** 조사 자체가 실패했는가(스크립트 오류·요소 소실). */
  failed: boolean
}

const EMPTY_TARGET_PROBE: EngageTargetProbe = { permalink: '', heading: '', listLike: false, failed: true }

// 인페이지 공통부 — 요소 하나를 받아 조상을 훑는다.
const ENGAGE_TARGET_FN = `function engageTarget(el){
  var out={permalink:'',heading:'',listLike:false};
  if(!el) return out;
  var doc=el.ownerDocument||document;
  var here='';try{here=(doc.defaultView&&doc.defaultView.location&&doc.defaultView.location.href)||'';}catch(e){}
  var hereNoHash=here.split('#')[0];
  var node=el, hops=0;
  var STOP={BODY:1,HTML:1,MAIN:1,NAV:1,HEADER:1,FOOTER:1,ASIDE:1};
  while(node && node.nodeType===1 && hops++<12){
    // 글 한 덩이를 넘어 문서 전체로 올라가면 **엉뚱한 글의 링크**를 그 글의 신원으로 삼게 된다
    // (사이드바·추천 목록). 문서 수준 컨테이너에 닿으면 그만 올라간다 — 못 찾으면 "모른다" 가 맞다.
    if(STOP[node.tagName]) break;
    try{ if((node.innerText||'').length>6000) break; }catch(e){}
    if(!out.permalink){
      var links=[];try{links=node.querySelectorAll('a[href]');}catch(e){links=[];}
      for(var i=0;i<links.length;i++){
        var h='';try{h=links[i].href||'';}catch(e){h='';}
        if(!h) continue;
        if(!/^https?:/i.test(h)) continue;
        if(h.split('#')[0]===hereNoHash) continue;   // 자기 페이지로 돌아오는 링크는 신원이 아니다
        out.permalink=h.slice(0,600); break;
      }
    }
    if(!out.heading){
      var hs=[];try{hs=node.querySelectorAll('h1,h2,h3,h4,[role=heading]');}catch(e){hs=[];}
      if(hs.length>0){
        var ht='';try{ht=(hs[0].innerText||hs[0].textContent||'').replace(/\\s+/g,' ').trim();}catch(e){}
        if(ht) out.heading=ht.slice(0,200);
      }
    }
    if(out.permalink) break;   // 퍼머링크를 찾으면 더 올라갈 이유가 없다(가장 가까운 글 단위)
    node=node.parentElement;
  }
  // 목록형 판정 — 같은 태그·같은 클래스의 형제가 여럿이면 피드로 본다.
  try{
    var p=el; var d=0;
    while(p&&p.nodeType===1&&d++<12){
      var par=p.parentElement; if(!par) break;
      var same=0, kids=par.children;
      for(var k=0;k<kids.length;k++){ if(kids[k].tagName===p.tagName && kids[k].className===p.className) same++; }
      if(same>=3 && (p.innerText||'').length>40){ out.listLike=true; break; }
      p=par;
    }
  }catch(e){}
  return out;

