      var ht='';try{ht=(hs[j].innerText||hs[j].textContent||'').replace(/\\s+/g,' ').trim();}catch(e){}
      if(ht){ out.heading=ht.slice(0,200); break; }
    }
  }
  if(out.permalink) break;   // 퍼머링크를 찾으면 더 올라갈 이유가 없다(가장 가까운 글 단위)
  node=node.parentElement;
}
return out;

