131	const CRC_TABLE = (() => {
132	  const table = new Uint32Array(256)
133	  for (let n = 0; n < 256; n++) {
134	    let c = n
135	    for (let k = 0; k < 8; k++) {
136	      c = (c & 1) ? (0xedb88320 ^ (c >>> 1)) : (c >>> 1)
137	    }
138	    table[n] = c >>> 0
139	  }
140	  return table
141	})()
