143	function crc32(buf) {
144	  let crc = 0xffffffff
145	  for (let i = 0; i < buf.length; i++) {
146	    crc = CRC_TABLE[(crc ^ buf[i]) & 0xff] ^ (crc >>> 8)
147	  }
148	  return (crc ^ 0xffffffff) >>> 0
149	}
