151	function pngChunk(type, data) {
152	  const typeBuf = Buffer.from(type, 'ascii')
153	  const lenBuf = Buffer.alloc(4)
154	  lenBuf.writeUInt32BE(data.length, 0)
155	  const crcBuf = Buffer.alloc(4)
156	  crcBuf.writeUInt32BE(crc32(Buffer.concat([typeBuf, data])), 0)
157	  return Buffer.concat([lenBuf, typeBuf, data, crcBuf])
