160	/** width x height 8비트 RGB(colorType=2) PNG 를 순수 zlib 으로 조립한다. colorFn(x,y) -> [r,g,b]. */
161	function encodePng(width, height, colorFn) {
162	  const rowBytes = width * 3
163	  const raw = Buffer.alloc((rowBytes + 1) * height)
164	  for (let y = 0; y < height; y++) {
165	    const rowStart = y * (rowBytes + 1)
166	    raw[rowStart] = 0 // 필터 없음
167	    for (let x = 0; x < width; x++) {
168	      const [r, g, b] = colorFn(x, y)
169	      const off = rowStart + 1 + x * 3
170	      raw[off] = r & 0xff
171	      raw[off + 1] = g & 0xff
172	      raw[off + 2] = b & 0xff
173	    }
174	  }
175	  const compressed = zlib.deflateSync(raw)
176	  const ihdr = Buffer.alloc(13)
177	  ihdr.writeUInt32BE(width, 0)
178	  ihdr.writeUInt32BE(height, 4)
179	  ihdr[8] = 8  // bit depth
180	  ihdr[9] = 2  // color type: truecolor RGB
181	  ihdr[10] = 0 // compression method
182	  ihdr[11] = 0 // filter method
183	  ihdr[12] = 0 // interlace method
184	  return Buffer.concat([
185	    PNG_SIGNATURE,
186	    pngChunk('IHDR', ihdr),
187	    pngChunk('IDAT', compressed),
188	    pngChunk('IEND', Buffer.alloc(0)),
189	  ])
190	}
