256	function parseMultipart(bodyBuf, boundary) {
257	  const boundaryBuf = Buffer.from(`--${boundary}`)
258	  const crlfcrlf = Buffer.from('\r\n\r\n')
259	  const parts = []
260	  let idx = bodyBuf.indexOf(boundaryBuf)
261	  while (idx !== -1) {
262	    const nextIdx = bodyBuf.indexOf(boundaryBuf, idx + boundaryBuf.length)
263	    if (nextIdx === -1) break
264	    let partStart = idx + boundaryBuf.length
265	    if (bodyBuf[partStart] === 0x0d && bodyBuf[partStart + 1] === 0x0a) partStart += 2
266	    let partEnd = nextIdx
267	    if (bodyBuf[partEnd - 2] === 0x0d && bodyBuf[partEnd - 1] === 0x0a) partEnd -= 2
268	    if (partEnd > partStart) parts.push(bodyBuf.subarray(partStart, partEnd))
269	    idx = nextIdx
270	  }
271	  const result = { fields: {}, files: {} }
272	  for (const part of parts) {
273	    const headerEnd = part.indexOf(crlfcrlf)
274	    if (headerEnd === -1) continue
275	    const headerStr = part.subarray(0, headerEnd).toString('utf8')
276	    const data = part.subarray(headerEnd + 4)
277	    const nameMatch = /name="([^"]*)"/.exec(headerStr)
278	    const filenameMatch = /filename="([^"]*)"/.exec(headerStr)
279	    const ctMatch = /Content-Type:\s*([^\r\n]+)/i.exec(headerStr)
280	    const name = nameMatch ? nameMatch[1] : ''
281	    if (!name) continue
282	    if (filenameMatch) {
283	      result.files[name] = {
284	        filename: filenameMatch[1],
285	        contentType: ctMatch ? ctMatch[1].trim() : 'application/octet-stream',
286	        data,
287	      }
288	    } else {
289	      result.fields[name] = data.toString('utf8')
290	    }
291	  }
292	  return result
293	}
