604	  async function handleSnsPublish(req, res) {
605	    const ct = req.headers['content-type'] || ''
606	    const boundaryMatch = /boundary=(?:"([^"]+)"|([^;]+))/i.exec(ct)
607	    if (!boundaryMatch) {
