611	    const bodyBuf = await readBodyBuffer(req)
612	    const parsed = parseMultipart(bodyBuf, boundary)
613	    const file = parsed.files['file']
614	    const caption = (parsed.fields['caption'] || '').trim()
615	    if (!file || !caption) {
616	      return sendJson(res, 400, { error: '파일 또는 문구 누락' })
617	    }
618	    const sha256 = crypto.createHash('sha256').update(file.data).digest('hex')
619	    const id = String(state.publishes.length + 1)
620	    state.publishes.push({ id, bytes: file.data.length, sha256, caption, at: Date.now() })
621	    return sendJson(res, 200, { id })
622	  }
