1723-  action: AgentAction,
1724-  // epoch(과제1) — 이 행동이 근거한 관찰의 세대 토큰. observePage() 가 돌려준 obs.epoch 를 그대로 넘기면,
1725-  // 그 사이 다른 관찰(탭 전환 후 재관찰 등)이 있었을 때 옛 ref 로 지금 화면의 다른 요소를 집지 않는다.
1726-  // 생략하면(하위호환) 세대·프레임 검사 없이 예전과 동일하게 동작한다.
1727-  opts?: { humanInput?: boolean; profile?: InputProfile; epoch?: string; allowedHosts?: string[] },
1728-): Promise<{ ok: boolean; detail: string }> {
1729-  if (wc.isDestroyed()) return { ok: false, detail: 'tab destroyed' }
1730-  const human = opts?.humanInput !== false
1731-  const prof = opts?.profile ?? PROFILE_STRICT
1732-  const epoch = opts?.epoch
1733-  if (!human) return execSynthetic(wc, action, epoch)
1734-  // 대상 해석을 한 번만 하고(프레임 오프셋 계산 포함) 실제 입력·합성 폴백이 같은 대상을 쓴다.
