const fs=require('fs');
const src=fs.readFileSync('app/dist/main/features/ai/page-actions.js','utf8');
const i=src.indexOf('function engageTarget(el)');
const start=src.lastIndexOf('`',i)+1, end=src.indexOf('`',i);
const engageTarget=new Function(src.slice(start,end)+'; return engageTarget;')();

const DOC={defaultView:{location:{href:'http://127.0.0.1:1/blog/feed'}}};
let ALL=[];
function mk(tag,attrs={},kids=[],text=''){
  const el={tagName:tag.toUpperCase(),nodeType:1,attrs,kids,text,parentElement:null,ownerDocument:DOC,
    getAttribute:k=>attrs[k]??null,
    get href(){return attrs.href},
    get innerText(){return (text+' '+kids.map(k=>k.innerText).join(' ')).trim()},
    get textContent(){return this.innerText},
    querySelectorAll(sel){const out=[];const walk=n=>{for(const c of n.kids){if(match(c,sel))out.push(c);walk(c)}};walk(this);return out},
    closest(sel){let n=this;while(n){if(match(n,sel))return n;n=n.parentElement}return null}};
  kids.forEach(k=>k.parentElement=el); ALL.push(el); return el;
}
function match(n,sel){
  return sel.split(',').map(s=>s.trim()).some(s=>{
    if(s==='form')return n.tagName==='FORM';
    if(s==='a[href]')return n.tagName==='A'&&!!n.attrs.href;
    if(/^h[1-4]$/.test(s))return n.tagName===s.toUpperCase();
    if(s==='[role=heading]')return n.attrs.role==='heading';
    if(s==='article'||s==='li'||s==='section')return n.tagName===s.toUpperCase();
    if(s==='textarea')return n.tagName==='TEXTAREA';
    if(s==='input[type=text]')return n.tagName==='INPUT'&&n.attrs.type==='text';
    if(s==='input:not([type])')return n.tagName==='INPUT'&&!n.attrs.type;
    if(s==='[contenteditable=true]')return n.attrs.contenteditable==='true';
    if(s==='button')return n.tagName==='BUTTON';
    if(s==='[role=button]')return n.attrs.role==='button';
    return false;
  });
}
function setDoc(root){ global.document={querySelectorAll:(sel)=>{const o=[];const w=n=>{for(const c of n.kids){if(match(c,sel))o.push(c);w(c)}};w(root);return o}}; }

function postBlock(id,title,draft,likeName){
  const link=id?mk('a',{href:'http://127.0.0.1:1/blog/post/'+id},[],title):null;
  const h3=title?mk('h3',{},link?[link]:[],link?'':title):null;
  const ta=mk('textarea',{},[],''); ta.value=draft;
  const btn=mk('button',{},[],'댓글 등록');
  const cform=mk('form',{action:'/blog/comment'},[mk('h3',{},[],'댓글'),ta,btn]);
  const lbtn=mk('button',{},[],likeName);
  const lform=mk('form',{action:'/blog/like'},[lbtn]);
  const kids=[]; if(h3)kids.push(h3); kids.push(mk('p',{},[],'본문 '+(title||id||'x')+' 입니다. 충분히 긴 본문.'),lform,cform);
  const art=mk('article',{},kids);
  return {art,btn,lbtn,ta};
}
function run(name,root,el){ setDoc(root); console.log(name.padEnd(22), JSON.stringify(engageTarget(el))); }

