ALL=[]; const f1=postBlock('f1','첫 글 제목','좋은 글 잘 봤습니다','♥ 좋아요');
const f2=postBlock('f2','둘째 글 제목','','♥ 좋아요');
const feedRoot=mk('body',{},[f1.art,f2.art]); feedRoot.tagName='BODY';
run('feed f1 댓글등록', feedRoot, f1.btn);
run('feed f2 댓글등록', feedRoot, f2.btn);
run('feed f1 좋아요',   feedRoot, f1.lbtn);

// 2) 단일 글 페이지: 제목이 body 직계(글 덩이 컨테이너 없음)
