const ta=mk('textarea',{},[],''); ta.value='좋은 글';
const btn=mk('button',{},[],'댓글 등록');
const cform=mk('form',{action:'/blog/comment'},[mk('h3',{},[],'댓글'),ta,btn]);
const lform=mk('form',{action:'/blog/like'},[mk('button',{},[],'♥ 좋아요')]);
const single=mk('body',{},[mk('h1',{},[],'단일 글 제목'),mk('p',{},[],'본문'),lform,cform]); single.tagName='BODY';
run('single 댓글등록', single, btn);

// 3) 익명 피드: 퍼머링크도 제목도 없음(글 2개)
ALL=[]; const a1=postBlock('','','초안 있음','♥ 좋아요'); const a2=postBlock('','','','♥ 좋아요');
const anon=mk('body',{},[a1.art,a2.art]); anon.tagName='BODY';
run('anon a1 댓글등록', anon, a1.btn);
EOF
