  if(!el) return out;
  function txt(n){ try{ return ((n.textContent||'')+'').replace(/\s+/g,' ').trim(); }catch(e){ return ''; } }
  // 클릭 대상이 버튼 안의 아이콘·글자일 수 있다 — 실제로 눌리는 컨트롤로 올라가서 본다.
  var ctl=el;
