cd "C:\Users\molma\Desktop\하네스\browser-build" && python - <<'PY'
import io
p='app/main/features/ai/agent.ts'
s=io.open(p,encoding='utf-8').read()

a="""function engageTargetKey(pageUrl: string, probe: { permalink: string; heading: string; peers: number; failed: boolean }): string {
  if (probe.failed) return ''
  if (probe.permalink) return normalizeTargetUrl(probe.permalink)
  const base = normalizeTargetUrl(pageUrl)
  if (probe.heading) {
    return `${base}#h=${createHash('sha1').update(probe.heading).digest('hex').slice(0, 16)}`
  }
  // 이 화면에 같은 종류의 대상이 하나뿐이면 페이지가 곧 그 글이다(평범한 글 상세 페이지).
  if (probe.peers === 1) return base
  return ''
}"""
b="""function engageTargetKey(pageUrl: string, probe: { permalink: string; heading: string; peers: number; failed: boolean }): string {
  const base = normalizeTargetUrl(pageUrl)
  // 조사 자체가 실패했다(요소가 사라졌거나 스크립트가 죽었다) — 이건 "글을 특정할 수 없다" 와 다르다.
  // 그 이유로 사용자를 멈춰 세우면 **틀린 이유로 묻는 것**이 된다. 페이지 단위로 거칠게 세어 두고
  // 진행한다(과차단은 안전한 방향이고, ref 가 죽었다면 클릭도 실패해 아래에서 되돌려진다).
  if (probe.failed) return base
  if (probe.permalink) return normalizeTargetUrl(probe.permalink)
  if (probe.heading) {
    // 제목이 신원이므로 주소의 쿼리는 노이즈다. `?comment=123`·`?page=2` 처럼 댓글을 달면 붙는
    // 파라미터를 키에 섞으면 **같은 글이 다른 키**가 되어 중복 방지가 샌다(2026-09-20 리뷰 H5).
    const noQuery = base.split('?')[0] ?? base
    return `${noQuery}#h=${createHash('sha1').update(probe.heading).digest('hex').slice(0, 16)}`
  }
  // 이 화면에 같은 종류의 대상이 하나뿐이면 페이지가 곧 그 글이다(평범한 글 상세 페이지).
  if (probe.peers === 1) return base
  return ''
}"""
assert s.count(a)==1
s=s.replace(a,b)

# L1 — 승인 후 동작을 정확히 알린다
a2="""                + `(${obs.url.slice(0, 120)}). 이 글에 대한 링크·제목을 찾지 못했습니다 — 같은 동작이 두 번 나가도`
                + ` 막을 수 없는 상태입니다. 진행하려면 "계속", 건너뛰려면 "건너뛰기" 라고 알려주세요.`,"""
b2="""                + `(${obs.url.slice(0, 120)}). 이 글의 링크·제목을 찾지 못해 글 단위로 셀 수 없습니다.`
                + ` "계속" 이라고 하시면 **이 화면 단위로 한 번만** 진행하고, 같은 화면의 다음 대상은 중복으로 보아`
                + ` 건너뜁니다. 건너뛰려면 "건너뛰기" 라고 알려주세요.`,"""
assert s.count(a2)==1
s=s.replace(a2,b2)
io.open(p,'w',encoding='utf-8').write(s)
print('ok')
